function toggleMenu(){
var open=document.getElementById('mm').classList.toggle('open');
document.querySelector('.hamburger').setAttribute('aria-expanded',open?'true':'false');
}
function closeMenu(){
document.getElementById('mm').classList.remove('open');
document.querySelector('.hamburger').setAttribute('aria-expanded','false');
}
window.addEventListener('scroll',closeMenu);
(function(){
var b=document.getElementById('cookieBanner');
if(localStorage.getItem('kca_cookies')) b.classList.add('hidden');
})();
function setCookies(choice){
localStorage.setItem('kca_cookies',choice);
document.getElementById('cookieBanner').classList.add('hidden');
if(choice==='accepted') loadGA();
}
var lastFocusedEl=null;
function trapFocus(container,e){
var f=container.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])');
if(!f.length) return;
var first=f[0],last=f[f.length-1];
if(e.key==='Tab'){
if(e.shiftKey && document.activeElement===first){e.preventDefault();last.focus();}
else if(!e.shiftKey && document.activeElement===last){e.preventDefault();first.focus();}
}
}
function openPrivacy(e){
if(e) e.preventDefault();
lastFocusedEl=document.activeElement;
document.getElementById('privacyModal').classList.add('open');
document.body.style.overflow='hidden';
document.querySelector('.pm-close').focus();
}
function closePrivacy(){
document.getElementById('privacyModal').classList.remove('open');
document.body.style.overflow='';
if(lastFocusedEl) lastFocusedEl.focus();
}
document.addEventListener('keydown',function(e){
if(e.key==='Escape') closePrivacy();
if(e.key==='Tab' && document.getElementById('privacyModal').classList.contains('open')) trapFocus(document.querySelector('.pm-inner'),e);
});
